#ifdef HAVE_ROM
using marble_physics::Mem;
using marble_physics::PLAYER;

// player fields
static const uint8_t PX = 0x0c, PY = 0x10, PZ = 0x14, VISIBLE = 0x1c, SX = 0x1e, SY = 0x20;
static const uint8_t GROUND_Z = 0x2a, MASKS = 0x38, SURFACE = 0x58, ANIM = 0x5a;
static const uint8_t SHARDS = 0x62, SHARDS_ON = 0x67, STARS = 0xa4, DEATHS = 0xd2;
static const uint8_t MASK_BYTES = 30, STAR_BYTES = 24;
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint8_t ST_EATEN = 5, ST_DISSOLVE = 9;
static const uint8_t RACE_AERIAL = 3;
static const uint8_t TAG_CATAPULT = 0x0a;

static uint8_t ram[marble_physics::RAM_SIZE];

// frame header drawn from +0x5a (states 1, 2, 5, 9) and the shard overlay +0x62, 0 if none
static uint32_t frameHdr(const Mem &m) {
  const uint8_t st = marble_physics::state(m);
  const bool drawn = st == marble_physics::DIZZY || st == marble_physics::BROKEN ||
                     st == ST_EATEN || st == ST_DISSOLVE;
  return m.rb(PLAYER + VISIBLE) && drawn ? marble_physics::animEntry(m.rl(PLAYER + ANIM)) : 0;
}

static uint32_t shardHdr(const Mem &m) {
  return m.rb(PLAYER + VISIBLE) && m.rb(PLAYER + SHARDS_ON) ? marble_physics::animEntry(m.rl(PLAYER + SHARDS)) : 0;
}

// first field of tick t that differs, nullptr if none
static const char *diff(const Mem &m, const MarbleAerialTick &t) {
  if (marble_physics::x(m) != t.x) { return "x"; }
  if (marble_physics::y(m) != t.y) { return "y"; }
  if (marble_physics::z(m) != t.z) { return "z"; }
  if (marble_physics::state(m) != t.state) { return "state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "vis"; }
  if (m.sw(PLAYER + SX) != t.sx) { return "sx"; }
  if (m.sw(PLAYER + SY) != t.sy) { return "sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "anim"; }
  if (frameHdr(m) != t.frame_hdr) { return "frame_hdr"; }
  if (shardHdr(m) != t.shard_hdr) { return "shard_hdr"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  return nullptr;
}

// marble.cpp logicTick tail: draw list sort 0x26f3e and the object build of the frame (reads
// the MO frames of every listed object, e.g. a gate's state 1 list)
static void drawTick(Mem &m) {
  static const int16_t CULL_MARGIN = 24;
  marble_drawlist::sort(m);
  marble_video::VideoState v = {};
  v.level = m.rw(marble_physics::RACE);
  marble_drawlist::build(m, m.sw(marble_physics::CAMERA), CULL_MARGIN, v);
}

// One main loop tick as marble_sim.py main_tick: 0x400010 and the camera long are inputs,
// then 0x1344c, band spawns (before the camera store), player 0x251de, enemies, slots, rng.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const uint16_t old = m.rw(marble_physics::CAMERA);
  if ((uint16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  m.wl(marble_physics::CAMERA_L, camera);
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  drawTick(m);
}

// MAME segments: gate pull and catch, CAUGHT stars, respawn where caught; 0x0d frame bounce;
// catapult throw; bounce box hits. Counts the CAUGHT ticks.
static void test_replay_aerial(void) {
  uint16_t caught = 0;
  for (uint8_t s = 0; s < MARBLE_AERIAL_SEGMENTS; s++) {
    const MarbleAerialSegment &seg = marble_aerials_segments[s];
    memset(ram, 0, sizeof(ram));
    for (uint8_t i = 0; i < seg.nram; i++) {
      const MarbleAerialRam &r = seg.ram[i];
      memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
    }
    Mem m(ram, seg.race);
    marble_drawlist::init(m);  // the fixture has no draw list; slot inserts need one

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleAerialTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      caught += marble_physics::state(m) == marble_physics::CAUGHT;
      const char *bad = diff(m, t);
      if (!bad) { continue; }

      char msg[160];
      snprintf(msg, sizeof(msg), "aerial segment %d tick %d: %s differs (state %d, expected %d)",
               s, k, bad, marble_physics::state(m), t.state);
      TEST_FAIL_MESSAGE(msg);
    }
  }
  TEST_ASSERT_TRUE_MESSAGE(caught > 0, "no CAUGHT ticks");
}

// ---------------------------------------------------------------- machine start path

// machine race start (marble.cpp beginRace) on a cleared work RAM
static void beginRace(uint8_t race) {
  memset(ram, 0, sizeof(ram));
  Mem m(ram, race);
  marble_physics::startRace(m, race);
  marble_camera::start(m, race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// marble.cpp logic tick with trackball deltas c6, c7
static void inputTick(Mem &m, int8_t c6, int8_t c7) {
  m.wl(marble_physics::FRAMES, m.rl(marble_physics::FRAMES) + 1);
  marble_objects::applyQueued(m);
  const int16_t oldCam = m.sw(marble_physics::CAMERA);
  const uint32_t oldL = m.rl(marble_physics::CAMERA_L);
  marble_camera::tick(m);
  const int16_t newCam = m.sw(marble_physics::CAMERA);
  if (newCam != oldCam) {  // as marble.cpp: spawns before the camera store
    const uint32_t newL = m.rl(marble_physics::CAMERA_L);
    m.wl(marble_physics::CAMERA_L, oldL);
    marble_objects::cameraBands(m, oldCam, newCam);
    m.wl(marble_physics::CAMERA_L, newL);
  }
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  drawTick(m);
}

// the marble put at pixel (x, y) on the floor, then ticks without input until the camera
// has scrolled there (band spawns)
static void placeAt(Mem &m, int16_t x, int16_t y) {
  static const uint16_t SETTLE = 400;
  m.wl(PLAYER + PX, (uint32_t)x << 16);
  m.wl(PLAYER + PY, (uint32_t)y << 16);
  m.wl(PLAYER + PZ, (uint32_t)marble_physics::cellHeight(m, PLAYER));
  m.wl(PLAYER + GROUND_Z, m.rl(PLAYER + PZ));
  for (uint16_t k = 0; k < SETTLE; k++) { inputTick(m, 0, 0); }
}

// MAME a5: on the zone line row above the first gate, pushed down and right: the gate (open
// after the zone line) catches the marble (CAUGHT, stars drawn), it reappears where it was
// caught (LOST, death count + 1), then rolls again
static void test_gate_catch(void) {
  static const uint16_t TICKS = 300;
  static const uint8_t DOWN_TICKS = 20, RIGHT_TICKS = 30;
  beginRace(RACE_AERIAL);
  Mem m(ram, RACE_AERIAL);
  placeAt(m, 268, 290);
  const uint16_t deaths = m.rw(PLAYER + DEATHS);

  uint16_t k = 0;
  for (; k < DOWN_TICKS + RIGHT_TICKS && marble_physics::state(m) == marble_physics::ROLL; k++) {
    inputTick(m, k < DOWN_TICKS ? -7 : 2, k < DOWN_TICKS ? 1 : 7);
  }
  while (marble_physics::state(m) == marble_physics::ROLL && k++ < TICKS) { inputTick(m, 0, 0); }
  TEST_ASSERT_EQUAL_UINT8_MESSAGE(marble_physics::CAUGHT, marble_physics::state(m), "not caught");
  const int32_t x = marble_physics::x(m), y = marble_physics::y(m);

  bool stars = false;
  while (marble_physics::state(m) == marble_physics::CAUGHT && k++ < TICKS) {
    inputTick(m, 0, 0);
    static const uint8_t ZERO[STAR_BYTES] = {};
    stars |= memcmp(ram + (PLAYER + STARS - marble_physics::RAM_BASE), ZERO, STAR_BYTES) != 0;
  }
  TEST_ASSERT_TRUE_MESSAGE(stars, "no stars while caught");
  TEST_ASSERT_EQUAL_UINT8(marble_physics::LOST, marble_physics::state(m));
  TEST_ASSERT_EQUAL_UINT16(deaths + 1, m.rw(PLAYER + DEATHS));

  while (marble_physics::state(m) == marble_physics::LOST && k++ < TICKS) { inputTick(m, 0, 0); }
  TEST_ASSERT_EQUAL_UINT8(marble_physics::ROLL, marble_physics::state(m));
  TEST_ASSERT_EQUAL_INT32(x, marble_physics::x(m));
  TEST_ASSERT_EQUAL_INT32(y, marble_physics::y(m));
}

// MAME a10: rolled onto the idle catapult arm: thrown (TUBE with the catapult tag), then flies
// higher than the arm before it lands
static void test_catapult(void) {
  static const uint16_t TICKS = 200;
  static const uint8_t PUSH_TICKS = 15;
  static const int32_t RISE = 0x100000;  // 16 px above the throw point
  beginRace(RACE_AERIAL);
  Mem m(ram, RACE_AERIAL);
  placeAt(m, 484, 560);

  uint16_t k = 0;
  while (marble_physics::state(m) != marble_physics::TUBE && k < TICKS) {
    inputTick(m, 0, k < PUSH_TICKS ? 9 : 0);
    k++;
  }
  TEST_ASSERT_EQUAL_UINT8_MESSAGE(marble_physics::TUBE, marble_physics::state(m), "not thrown");
  TEST_ASSERT_EQUAL_UINT8(TAG_CATAPULT, m.rb(PLAYER + SURFACE));
  const int32_t z0 = marble_physics::z(m);

  int32_t top = z0;
  while (k++ < TICKS && marble_physics::state(m) != marble_physics::DIZZY) {
    inputTick(m, 0, 0);
    if (marble_physics::z(m) > top) { top = marble_physics::z(m); }
  }
  TEST_ASSERT_TRUE_MESSAGE(top > z0 + RISE, "not thrown up");
  TEST_ASSERT_EQUAL_UINT8(marble_physics::DIZZY, marble_physics::state(m));
}
#endif

int main(int, char **) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  Arena::init();
  Arena::reserve(&marble_arena_plan);  // like switchTo()
  marble_physics::loadRom();
  RUN_TEST(test_replay_aerial);
  RUN_TEST(test_gate_catch);
  RUN_TEST(test_catapult);
#else
  TEST_IGNORE_MESSAGE("marble_rom.h missing, run romconv ./convert.sh marble");
#endif
  return UNITY_END();
}
